def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if not alive:
        return float(min(budget, DAILY_SALARY * 0.35))

    prev_bids = []
    aggressive_bids = []
    weak_count = 0
    urgent_opp = 0

    for opp in alive:
        prev = opp.get('previous_trace', {})
        bid = None
        if prev:
            bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))
            if bid >= DAILY_SALARY * 0.85:
                aggressive_bids.append(float(bid))
            if bid <= DAILY_SALARY * 0.45:
                weak_count += 1
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 2:
            urgent_opp += 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0.0

    scarcity = supply < WATER_REQ * (len(alive) + 1)
    very_tight = supply <= WATER_REQ * max(1, len(alive))
    my_urgent = hp <= 3 or no_water >= 2
    my_caution = hp <= 5 or no_water >= 1

    if my_urgent:
        target = max(DAILY_SALARY * 0.95, highest_prev + 2.5)
    elif very_tight:
        if aggressive_bids:
            target = max(DAILY_SALARY * 0.82, highest_prev + 1.6)
        else:
            target = max(DAILY_SALARY * 0.68, avg_prev + 2.0)
    elif scarcity:
        if urgent_opp >= 2:
            target = max(DAILY_SALARY * 0.72, highest_prev + 1.2)
        else:
            target = max(DAILY_SALARY * 0.58, avg_prev + 1.0)
    else:
        if weak_count >= len(prev_bids) / 2.0:
            target = DAILY_SALARY * 0.34
        else:
            target = max(DAILY_SALARY * 0.4, avg_prev * 0.78)

    if hp >= 8 and no_water == 0 and not my_caution and not very_tight:
        target *= 0.92
    if day >= 8 and budget < DAILY_SALARY * 2.2:
        target *= 0.9
    if budget < DAILY_SALARY * 1.2 and not my_urgent:
        target = min(target, DAILY_SALARY * 0.62)

    floor_bid = 0.0
    if my_urgent:
        floor_bid = DAILY_SALARY * 0.78
    elif my_caution and scarcity:
        floor_bid = DAILY_SALARY * 0.56
    elif scarcity:
        floor_bid = DAILY_SALARY * 0.44
    else:
        floor_bid = DAILY_SALARY * 0.28

    bid = max(target, floor_bid)
    bid = min(bid, budget)
    if bid < 0:
        bid = 0.0
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    # Identify alive opponents and collect yesterday bids
    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opps.append(opp)

    if not alive_opps:
        return float(min(my_status['budget'], DAILY_SALARY * 0.4))

    yesterday_bids = []
    yesterday_hp_after = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid', None)
        if bid is not None:
            try:
                yesterday_bids.append(float(bid))
            except Exception:
                pass
        hp_after = prev.get('hp_after', None)
        if hp_after is not None:
            try:
                yesterday_hp_after.append(float(hp_after))
            except Exception:
                pass

    # If someone previously bid extremely high, assume scarcity and bid up to compete.
    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # Base aggressiveness tuned for medium scenario: moderate bid unless pressure is high.
    # Use supply to scale: higher supply reduces need to overbid.
    supply_factor = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY) if MAX_SUPPLY != MIN_SUPPLY else 0.5
    supply_factor = max(0.0, min(1.0, supply_factor))

    # Estimate how many water units exist relative to our requirement.
    # This is a heuristic to decide how competitive bidding likely is.
    units = supply / float(WATER_REQ)

    # If yesterday shows high bids, compete; otherwise bid just enough.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        # Cindy-like behavior: others may be protecting survival.
        # If our hp is low, go higher; else conserve budget.
        if float(my_status['hp']) <= 2:
            target = DAILY_SALARY * 0.95
        else:
            target = DAILY_SALARY * (0.55 + 0.35 * (1.0 - supply_factor))
    elif highest_prev_bid >= DAILY_SALARY * 0.45:
        # Some opponents were active but not extreme.
        target = max(DAILY_SALARY * 0.45, highest_prev_bid * 0.75)
        target = target * (0.85 + 0.3 * (1.0 - supply_factor))
    else:
        # Low bids yesterday: likely underbidding; we can take advantage with moderate bid.
        target = DAILY_SALARY * (0.40 + 0.25 * (1.0 - supply_factor))
        # If supply is tight (units < 2), increase.
        if units < 2.0:
            target = target * 1.15

    # Ensure we don't bid beyond our budget.
    budget = float(my_status['budget'])
    if budget <= 0.0:
        return 0.0

    # If we are close to running out of water days, increase bid.
    no_water_days = int(my_status.get('no_water_days', 0))
    hp = float(my_status['hp'])
    if no_water_days >= 2 or hp <= 2:
        target = max(target, DAILY_SALARY * 0.75)

    # Cap bid to budget and keep within a sensible range.
    bid = float(min(budget, max(0.0, target)))
    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    yesterday_bids = []
    for opp_id, opp in opponents_status.items():
        if opp['alive'] and opp.get('previous_trace') and opp['previous_trace'].get('bid') is not None:
            yesterday_bids.append(opp['previous_trace']['bid'])

    if no_water_days >= 1:
        base = DAILY_SALARY * 0.9
    elif hp <= 2:
        base = DAILY_SALARY * 0.8
    elif hp <= 5:
        base = DAILY_SALARY * 0.6
    else:
        base = DAILY_SALARY * 0.4

    if yesterday_bids:
        max_yesterday = max(yesterday_bids)
        if max_yesterday > DAILY_SALARY * 0.85:
            if base < DAILY_SALARY * 0.6:
                base = DAILY_SALARY * 0.6
        avg_yesterday = sum(yesterday_bids) / len(yesterday_bids)
        if avg_yesterday > DAILY_SALARY * 0.7:
            base = max(base, avg_yesterday * 0.8)

    bid = min(budget, base)
    bid = max(0, bid)
    return bid
